args.Content:
/* ==========================================================================
   The Sweet Oven - Shared Stylesheet
   Loaded AFTER Bootstrap 5.3.3 CDN
   ========================================================================== */

/* --------------------------------------------------------------------------
   1. CSS Custom Properties (Palette & Typography)
   -------------------------------------------------------------------------- */
:root {
  /* Required Brand Palette */
  --color-cream: #FFF8EE;        /* Primary page background */
  --color-brown: #4A2C1D;        /* Primary text & dark surfaces */
  --color-caramel: #B5601E;      /* Primary buttons & accents */
  --color-pink: #F3B6C0;         /* Highlights, tags, subtle accents */

  /* Supporting Accessible Tints & Shades */
  --color-caramel-dark: #8F4812; /* Hover state & small text links (>= 4.5:1 on cream) */
  --color-pink-soft: #FCE8EC;    /* Soft highlight surface */
  --color-surface: #FFFFFF;      /* Card & input background */
  --color-border: #DFCBB7;       /* Warm border for cards & dividers */
  --color-input-border: #B89D85; /* Higher-contrast border for form inputs */
  --color-muted: #6E4F3E;        /* Secondary readable text (>= 6.5:1 on cream/white) */

  /* Typography (Google Fonts with reliable system fallbacks) */
  --font-heading: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --font-body: 'Nunito', 'Segoe UI', Roboto, Arial, sans-serif;

  /* Radii & Shadows */
  --radius-sm: 0.5rem;
  --radius-md: 0.875rem;
  --radius-lg: 1.25rem;
  --shadow-soft: 0 4px 14px rgba(74, 44, 29, 0.08);
  --shadow-hover: 0 8px 22px rgba(74, 44, 29, 0.14);

  /* Align Bootstrap 5 CSS variables with our theme */
  --bs-body-bg: var(--color-cream);
  --bs-body-color: var(--color-brown);
  --bs-body-font-family: var(--font-body);
  --bs-primary: var(--color-caramel);
  --bs-primary-rgb: 181, 96, 30;
  --bs-link-color: var(--color-caramel-dark);
  --bs-link-hover-color: var(--color-brown);
  --bs-border-color: var(--color-border);
}

/* --------------------------------------------------------------------------
   2. Base Layout & Typography
   -------------------------------------------------------------------------- */
body {
  background-color: var(--color-cream);
  color: var(--color-brown);
  font-family: var(--font-body);
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

main {
  flex: 1 0 auto;
}

h1, h2, h3, h4, h5, h6,
.font-heading {
  font-family: var(--font-heading);
  color: var(--color-brown);
  font-weight: 700;
  line-height: 1.25;
}

a {
  color: var(--color-caramel-dark);
  text-underline-offset: 0.2em;
}

a:hover {
  color: var(--color-brown);
}

.text-muted-bakery {
  color: var(--color-muted);
}

/* Accessibility: Skip to main content link */
.skip-link {
  position: absolute;
  top: -100px;
  left: 1rem;
  z-index: 1100;
  background-color: var(--color-brown);
  color: var(--color-cream);
  padding: 0.6rem 1rem;
  border-radius: var(--radius-sm);
  font-weight: 700;
  text-decoration: none;
}

.skip-link:focus {
  top: 1rem;
  color: var(--color-cream);
}

/* --------------------------------------------------------------------------
   3. Visible Focus States (Keyboard Accessibility)
   -------------------------------------------------------------------------- */
a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
.btn:focus-visible,
.nav-link:focus-visible,
.navbar-toggler:focus-visible {
  outline: 3px solid var(--color-caramel);
  outline-offset: 2px;
  box-shadow: 0 0 0 4px rgba(243, 182, 192, 0.55);
}

/* --------------------------------------------------------------------------
   4. Shared Header & Navbar
   -------------------------------------------------------------------------- */
.site-header {
  background-color: var(--color-surface);
  border-bottom: 3px solid var(--color-pink);
  box-shadow: 0 2px 10px rgba(74, 44, 29, 0.06);
}

.site-header .navbar-brand {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
  color: var(--color-brown);
  font-family: var(--font-heading);
  font-size: 1.4rem;
  font-weight: 700;
  text-decoration: none;
}

.site-header .navbar-brand:hover {
  color: var(--color-caramel-dark);
}

.brand-logo {
  width: 42px;
  height: 42px;
  flex-shrink: 0;
}

.site-header .nav-link {
  color: var(--color-brown);
  font-weight: 700;
  padding: 0.5rem 0.9rem;
  border-radius: var(--radius-sm);
  transition: background-color 0.2s ease, color 0.2s ease;
}

.site-header .nav-link:hover {
  background-color: var(--color-pink-soft);
  color: var(--color-brown);
}

.site-header .nav-link.active,
.site-header .nav-link[aria-current="page"] {
  background-color: var(--color-pink);
  color: var(--color-brown);
}

/* Highlight Cart button in navbar while keeping high contrast */
.site-header .nav-link-cart {
  background-color: var(--color-caramel);
  color: #FFFFFF;
}

.site-header .nav-link-cart:hover,
.site-header .nav-link-cart.active,
.site-header .nav-link-cart[aria-current="page"] {
  background-color: var(--color-caramel-dark);
  color: #FFFFFF;
}

/* Mobile hamburger button styling */
.site-header .navbar-toggler {
  border: 2px solid var(--color-brown);
  padding: 0.4rem 0.65rem;
  color: var(--color-brown);
}

.site-header .navbar-toggler-icon {
  background-image: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 30 30'%3e%3cpath stroke='%234A2C1D' stroke-linecap='round' stroke-miterlimit='10' stroke-width='2.4' d='M4 7h22M4 15h22M4 23h22'/%3e%3c/svg%3e");
}

/* --------------------------------------------------------------------------
   5. Buttons
   -------------------------------------------------------------------------- */
.btn {
  font-weight: 700;
  border-radius: var(--radius-sm);
  padding: 0.55rem 1.2rem;
  transition: background-color 0.2s ease, border-color 0.2s ease, transform 0.15s ease;
}

/* Caramel primary button (white on #B5601E = 4.51:1 WCAG AA contrast) */
.btn-bakery,
.btn-primary {
  background-color: var(--color-caramel);
  border-color: var(--color-caramel);
  color: #FFFFFF;
}

.btn-bakery:hover,
.btn-bakery:active,
.btn-primary:hover,
.btn-primary:active,
.btn-primary:focus {
  background-color: var(--color-caramel-dark);
  border-color: var(--color-caramel-dark);
  color: #FFFFFF;
}

/* Outline caramel/brown button with pink highlight hover */
.btn-outline-bakery {
  background-color: transparent;
  border: 2px solid var(--color-caramel);
  color: var(--color-brown);
}

.btn-outline-bakery:hover,
.btn-outline-bakery:active {
  background-color: var(--color-pink);
  border-color: var(--color-brown);
  color: var(--color-brown);
}

/* Pink highlight button with dark brown text (7.38:1 contrast) */
.btn-pink {
  background-color: var(--color-pink);
  border-color: var(--color-pink);
  color: var(--color-brown);
}

.btn-pink:hover,
.btn-pink:active {
  background-color: #EAA0AD;
  border-color: var(--color-brown);
  color: var(--color-brown);
}

/* --------------------------------------------------------------------------
   6. Cards & Highlight Badges
   -------------------------------------------------------------------------- */
.card,
.bakery-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-soft);
  color: var(--color-brown);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.card-hover:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-hover);
}

.card-header {
  background-color: var(--color-pink-soft);
  border-bottom: 1px solid var(--color-border);
  color: var(--color-brown);
  font-weight: 700;
}

.badge-pink,
.highlight-pink {
  background-color: var(--color-pink);
  color: var(--color-brown);
  font-weight: 700;
}

.section-highlight {
  background-color: var(--color-pink-soft);
  border: 1px solid var(--color-pink);
  border-radius: var(--radius-lg);
}

/* --------------------------------------------------------------------------
   7. Form Inputs & Labels
   -------------------------------------------------------------------------- */
.form-label {
  color: var(--color-brown);
  font-weight: 700;
  margin-bottom: 0.35rem;
}

.form-control,
.form-select {
  background-color: var(--color-surface);
  color: var(--color-brown);
  border: 1.5px solid var(--color-input-border);
  border-radius: var(--radius-sm);
  padding: 0.55rem 0.85rem;
}

.form-control::placeholder {
  color: var(--color-muted);
  opacity: 0.85;
}

.form-control:focus,
.form-select:focus {
  background-color: var(--color-surface);
  color: var(--color-brown);
  border-color: var(--color-caramel);
  box-shadow: 0 0 0 0.25rem rgba(181, 96, 30, 0.25);
}

.form-check-input {
  border: 1.5px solid var(--color-brown);
}

.form-check-input:checked {
  background-color: var(--color-caramel);
  border-color: var(--color-caramel);
}

/* --------------------------------------------------------------------------
   8. Shared Footer
   -------------------------------------------------------------------------- */
.site-footer {
  background-color: var(--color-brown);
  color: var(--color-cream);
  border-top: 4px solid var(--color-caramel);
}

.site-footer h2,
.site-footer h3,
.site-footer .footer-heading {
  font-family: var(--font-heading);
  color: var(--color-pink);
  font-size: 1.15rem;
  font-weight: 700;
  margin-bottom: 0.75rem;
}

.site-footer a {
  color: var(--color-cream);
  text-decoration: none;
}

.site-footer a:hover {
  color: var(--color-pink);
  text-decoration: underline;
}

.site-footer a:focus-visible {
  outline: 3px solid var(--color-pink);
  outline-offset: 2px;
  box-shadow: none;
}

.site-footer .footer-divider {
  border-color: rgba(255, 248, 238, 0.2);
}

.site-footer .footer-copyright {
  color: var(--color-cream);
  opacity: 0.9;
}

args.CommandLine:
Get-ChildItem -Force -Recurse -Filter "*.html" | Where-Object { $_.FullName -notmatch '\\\.git(\\|$)' } | ForEach-Object {
  $matches = Select-String -Path $_.FullName -Pattern 'bootstrap\.bundle\.min\.js'
  Write-Output "$($_.FullName) | Matches: $($matches.Count)"
  $matches | ForEach-Object { Write-Output "  L$($_.LineNumber): $($_.Line)" }
}
